import type { InitData } from '@supabase/mcp-utils';
import { z } from 'zod/v4';
import { AWS_REGION_CODES } from '../regions.js';

export type SuccessResponse = {
  success: true;
};

export const storageBucketSchema = z.object({
  id: z.string(),
  name: z.string(),
  owner: z.string(),
  created_at: z.string(),
  updated_at: z.string(),
  public: z.boolean(),
});

export const storageConfigSchema = z.object({
  fileSizeLimit: z.number().int().min(0).max(536_870_912_000), // 500GB
  features: z.object({
    imageTransformation: z.object({ enabled: z.boolean() }),
    s3Protocol: z.object({ enabled: z.boolean() }),
  }),
});

export const organizationSchema = z.object({
  id: z.string(),
  name: z.string(),
  plan: z.string().optional(),
  allowed_release_channels: z.array(z.string()),
  opt_in_tags: z.array(z.string()),
});

export const projectSchema = z.object({
  id: z.string(),
  ref: z.string(),
  organization_id: z.string(),
  organization_slug: z.string(),
  name: z.string(),
  status: z.string(),
  created_at: z.string(),
  region: z.string(),
});

export const branchSchema = z.object({
  id: z.string(),
  name: z.string(),
  project_ref: z.string(),
  parent_project_ref: z.string(),
  is_default: z.boolean(),
  git_branch: z.string().optional(),
  pr_number: z.number().optional(),
  latest_check_run_id: z.number().optional(),
  persistent: z.boolean(),
  status: z.enum([
    'CREATING_PROJECT',
    'RUNNING_MIGRATIONS',
    'MIGRATIONS_PASSED',
    'MIGRATIONS_FAILED',
    'FUNCTIONS_DEPLOYED',
    'FUNCTIONS_FAILED',
  ]),
  created_at: z.string(),
  updated_at: z.string(),
});

export const edgeFunctionSchema = z.object({
  id: z.string(),
  slug: z.string(),
  name: z.string(),
  status: z.string(),
  version: z.number(),
  created_at: z.number().optional(),
  updated_at: z.number().optional(),
  verify_jwt: z.boolean().optional(),
  import_map: z.boolean().optional(),
  import_map_path: z.string().optional(),
  entrypoint_path: z.string().optional(),
});

export const edgeFunctionWithBodySchema = edgeFunctionSchema.extend({
  files: z.array(
    z.object({
      name: z.string(),
      content: z.string(),
    })
  ),
});

export const createProjectOptionsSchema = z.object({
  name: z.string().min(1).max(256),
  organization_id: z.string(),
  region: z.enum(AWS_REGION_CODES),
  db_pass: z.string().optional(),
});

export const createBranchOptionsSchema = z.object({
  name: z.string().min(1),
});

export const resetBranchOptionsSchema = z.object({
  migration_version: z.string().optional(),
});

export const deployEdgeFunctionOptionsSchema = z.object({
  name: z.string().regex(/^[A-Za-z][A-Za-z0-9_-]*$/),
  entrypoint_path: z.string(),
  import_map_path: z.string().optional(),
  verify_jwt: z.boolean().optional(),
  files: z.array(
    z.object({
      name: z.string(),
      content: z.string(),
    })
  ),
});

export class ResultTooLargeError extends Error {
  override name = 'ResultTooLargeError';
}

export const executeSqlOptionsSchema = z.object({
  query: z.string().min(1),
  parameters: z.array(z.unknown()).optional(),
  read_only: z.boolean().optional(),
  /**
   * Largest result, in bytes of JSON, the caller will use. Platforms that
   * buffer results in shared server memory should stop reading at this limit
   * and throw an error whose name is 'ResultTooLargeError'. Callers also check
   * the rows they get back.
   */
  max_result_bytes: z.number().int().nonnegative().optional(),
});

export const applyMigrationOptionsSchema = z.object({
  name: z.string().min(1),
  query: z.string().min(1),
});

export const migrationSchema = z.object({
  version: z.string(),
  name: z.string().optional(),
});

export const logsServiceSchema = z.enum([
  'api',
  'branch-action',
  'postgres',
  'edge-function',
  'edge-function-runtime',
  'auth',
  'storage',
  'realtime',
]);

export const getLogsOptionsSchema = z.object({
  service: logsServiceSchema,
  iso_timestamp_start: z.string().optional(),
  iso_timestamp_end: z.string().optional(),
});

export const queryLogsOptionsSchema = z.object({
  sql: z.string().min(1),
  iso_timestamp_start: z.string().optional(),
  iso_timestamp_end: z.string().optional(),
  /**
   * Stop reading the response once it exceeds this many bytes and fail the
   * call with an error whose name is 'ResultTooLargeError'. Omitted means no
   * limit; callers still check the rows they get back.
   */
  max_result_bytes: z.number().int().nonnegative().optional(),
});

export const generateTypescriptTypesResultSchema = z.object({
  types: z.string(),
});

const notebookUserSchema = z
  .object({
    id: z.number(),
    username: z.string(),
  })
  .nullable();

const notebookChartConfigSchema = z.object({
  type: z.enum(['bar', 'line']),
  x_column: z.string(),
  y_series: z.array(z.object({ column: z.string() })),
  scale: z.enum(['linear', 'log']),
  cumulative: z.boolean(),
  show_labels: z.boolean(),
});

const notebookMarkdownCellSchema = z.object({
  id: z.string(),
  type: z.literal('markdown'),
  text: z.string(),
});

const notebookDatabaseCellSchema = z.object({
  id: z.string(),
  type: z.literal('database'),
  sql: z.string(),
  row_limit: z.number(),
  database_identifier: z.string().optional(),
  title: z.string().optional(),
  view: z.enum(['table', 'chart']).optional(),
  chart: notebookChartConfigSchema.optional(),
});

const notebookLogTimeUnitSchema = z.enum([
  'minute',
  'hour',
  'day',
  'week',
  'month',
  'year',
]);

const notebookLogTimeRangeSchema = z.union([
  z.object({
    type: z.literal('absolute'),
    start: z.string(),
    end: z.string(),
  }),
  z.object({
    type: z.literal('relative'),
    unit: notebookLogTimeUnitSchema,
    amount: z.number(),
  }),
]);

const notebookLogCellSchema = z.object({
  id: z.string(),
  type: z.literal('log'),
  sql: z.string(),
  time_range: notebookLogTimeRangeSchema,
  title: z.string().optional(),
  view: z.enum(['table', 'chart']).optional(),
  chart: notebookChartConfigSchema.optional(),
});

export const notebookCellSchema = z.discriminatedUnion('type', [
  notebookMarkdownCellSchema,
  notebookDatabaseCellSchema,
  notebookLogCellSchema,
]);

// Cell keys to create, without server-assigned ids. Stricter than the read
// schemas above, so a misspelled cell key fails instead of being dropped.
const newNotebookChartConfigSchema = notebookChartConfigSchema
  .extend({
    y_series: z.array(
      notebookChartConfigSchema.shape.y_series.element.strict()
    ),
  })
  .strict();

const newNotebookSqlSchema = z.string().trim().min(1);

const newNotebookCellSchema = z.discriminatedUnion('type', [
  notebookMarkdownCellSchema.omit({ id: true }).strict(),
  notebookDatabaseCellSchema
    .omit({ id: true })
    .extend({
      sql: newNotebookSqlSchema,
      row_limit: z.number().int().positive(),
      database_identifier: z.string().min(1).optional(),
      chart: newNotebookChartConfigSchema.optional(),
    })
    .strict(),
  notebookLogCellSchema
    .omit({ id: true })
    .extend({
      sql: newNotebookSqlSchema,
      time_range: z.discriminatedUnion('type', [
        z
          .object({
            type: z.literal('absolute'),
            start: z.iso.datetime({ offset: true }),
            end: z.iso.datetime({ offset: true }),
          })
          .strict()
          .refine((range) => Date.parse(range.end) > Date.parse(range.start), {
            message: 'The end must be later than the start of the range.',
            path: ['end'],
          }),
        z
          .object({
            type: z.literal('relative'),
            unit: notebookLogTimeUnitSchema,
            amount: z.number().int().positive(),
          })
          .strict(),
      ]),
      chart: newNotebookChartConfigSchema.optional(),
    })
    .strict(),
]);

export const createNotebookOptionsSchema = z.object({
  name: z.string().trim().min(1),
  description: z.string().optional(),
  content: z.object({
    cells: z.array(newNotebookCellSchema),
  }),
});

export const notebookSchema = z.object({
  id: z.string(),
  name: z.string(),
  description: z.string().nullable(),
  favorite: z.boolean(),
  inserted_at: z.string(),
  updated_at: z.string(),
  owner: notebookUserSchema,
  updated_by: notebookUserSchema,
});

export const notebookWithContentSchema = notebookSchema.extend({
  content: z.object({
    schema_version: z.number(),
    cells: z.array(notebookCellSchema),
  }),
});

export type Organization = z.infer<typeof organizationSchema>;
export type Project = z.infer<typeof projectSchema>;
/** The project detail endpoint also reports the database engine. */
export type ProjectDetail = Project & {
  database?: { postgres_engine?: string };
};
export type Branch = z.infer<typeof branchSchema>;
export type EdgeFunction = z.infer<typeof edgeFunctionSchema>;
export type EdgeFunctionWithBody = z.infer<typeof edgeFunctionWithBodySchema>;

export type CreateProjectOptions = z.infer<typeof createProjectOptionsSchema>;
export type CreateBranchOptions = z.infer<typeof createBranchOptionsSchema>;
export type ResetBranchOptions = z.infer<typeof resetBranchOptionsSchema>;
export type DeployEdgeFunctionOptions = z.infer<
  typeof deployEdgeFunctionOptionsSchema
>;

export type ExecuteSqlOptions = z.infer<typeof executeSqlOptionsSchema>;
export type ApplyMigrationOptions = z.infer<typeof applyMigrationOptionsSchema>;
export type Migration = z.infer<typeof migrationSchema>;
export type ListMigrationsResult = z.infer<typeof migrationSchema>;

export type LogsService = z.infer<typeof logsServiceSchema>;
export type GetLogsOptions = z.infer<typeof getLogsOptionsSchema>;
export type QueryLogsOptions = z.infer<typeof queryLogsOptionsSchema>;
export type GenerateTypescriptTypesResult = z.infer<
  typeof generateTypescriptTypesResultSchema
>;

export type StorageConfig = z.infer<typeof storageConfigSchema>;
export type StorageBucket = z.infer<typeof storageBucketSchema>;

export type NotebookCell = z.infer<typeof notebookCellSchema>;
export type CreateNotebookOptions = z.infer<typeof createNotebookOptionsSchema>;
export type Notebook = z.infer<typeof notebookSchema>;
export type NotebookWithContent = z.infer<typeof notebookWithContentSchema>;

export type DatabaseOperations = {
  executeSql<T>(projectId: string, options: ExecuteSqlOptions): Promise<T[]>;
  listMigrations(projectId: string): Promise<Migration[]>;
  applyMigration(
    projectId: string,
    options: ApplyMigrationOptions
  ): Promise<void>;
};

export type AccountOperations = {
  listOrganizations(): Promise<{ id: string; slug: string; name: string }[]>;
  getOrganization(organizationId: string): Promise<Organization>;
  listProjects(): Promise<Project[]>;
  getProject(projectId: string): Promise<ProjectDetail>;
  createProject(options: CreateProjectOptions): Promise<Project>;
  pauseProject(projectId: string): Promise<void>;
  restoreProject(projectId: string): Promise<void>;
};

export type EdgeFunctionsOperations = {
  listEdgeFunctions(projectId: string): Promise<EdgeFunction[]>;
  getEdgeFunction(
    projectId: string,
    functionSlug: string
  ): Promise<EdgeFunctionWithBody>;
  deployEdgeFunction(
    projectId: string,
    options: DeployEdgeFunctionOptions
  ): Promise<Omit<EdgeFunction, 'files'>>;
};

/**
 * SQL dialect that a platform's logs endpoint speaks. Selects the
 * dialect-appropriate `query_logs` description and `sql` parameter hint so a
 * single tool can roll out across environments that back logs with different
 * engines (hosted ClickHouse vs. self-hosted/CLI BigQuery).
 */
export type LogsDialect = 'clickhouse' | 'bigquery';

export type DebuggingOperations = {
  /**
   * SQL dialect accepted by `queryLogs`. Defaults to `'clickhouse'` when unset,
   * preserving the behavior of platforms that predate this field.
   */
  logsDialect?: LogsDialect;
  getLogs(projectId: string, options: GetLogsOptions): Promise<unknown>;
  queryLogs?(projectId: string, options: QueryLogsOptions): Promise<unknown>;
  getSecurityAdvisors(projectId: string): Promise<unknown>;
  getPerformanceAdvisors(projectId: string): Promise<unknown>;
  getHealthAdvisors?(projectId: string): Promise<unknown>;
};

export const apiKeyTypeSchema = z.enum(['legacy', 'publishable']);
export type ApiKeyType = z.infer<typeof apiKeyTypeSchema>;

export type ApiKey = {
  api_key: string;
  name: string;
  type: ApiKeyType;
  description?: string;
  id?: string;
  disabled?: boolean;
};

export type DevelopmentOperations = {
  getProjectUrl(projectId: string): Promise<string>;
  getPublishableKeys(projectId: string): Promise<ApiKey[]>;
  generateTypescriptTypes(
    projectId: string
  ): Promise<GenerateTypescriptTypesResult>;
};

export type StorageOperations = {
  getStorageConfig(projectId: string): Promise<StorageConfig>;
  updateStorageConfig(projectId: string, config: StorageConfig): Promise<void>;
  listAllBuckets(projectId: string): Promise<StorageBucket[]>;
};

export type BranchingOperations = {
  listBranches(projectId: string): Promise<Branch[]>;
  createBranch(
    projectId: string,
    options: CreateBranchOptions
  ): Promise<Branch>;
  deleteBranch(branchId: string): Promise<void>;
  mergeBranch(branchId: string): Promise<void>;
  resetBranch(branchId: string, options: ResetBranchOptions): Promise<void>;
  rebaseBranch(branchId: string): Promise<void>;
};

/**
 * Returns only the `updated_at` timestamp of the named secret, never its
 * value or digest.
 */
export type SecretOperations = {
  getUpdatedAt(projectId: string, name: string): Promise<Date | undefined>;
};

export type NotebookOperations = {
  /** Optional for platforms that only support reading notebooks. */
  createNotebook?(
    projectId: string,
    options: CreateNotebookOptions
  ): Promise<NotebookWithContent>;
  listNotebooks(projectId: string): Promise<Notebook[]>;
  getNotebook(
    projectId: string,
    notebookId: string
  ): Promise<NotebookWithContent>;
  deleteNotebook(projectId: string, notebookId: string): Promise<void>;
};

export type FeedbackOperations = {
  submit(input: {
    feedback: string;
    projectId?: string;
    clientInfo?: { name: string; version: string };
  }): Promise<{ deleteToken: string }>;
  delete(input: {
    deleteToken: string;
    projectId?: string;
  }): Promise<{ deleted: boolean }>;
};

export type SupabasePlatform = {
  init?(info: InitData): Promise<void>;
  account?: AccountOperations;
  database?: DatabaseOperations;
  functions?: EdgeFunctionsOperations;
  debugging?: DebuggingOperations;
  development?: DevelopmentOperations;
  storage?: StorageOperations;
  branching?: BranchingOperations;
  secrets?: SecretOperations;
  notebooks?: NotebookOperations;
  feedback?: FeedbackOperations;
};
